CREATE FUNCTION public.aicrm_questionnaire_public_receipt_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.questionnaire_public_submission_receipts WHERE id=NEW.id AND state='completed') THEN RAISE EXCEPTION 'public receipt must complete in reservation transaction' USING ERRCODE='23514'; END IF; RETURN NULL; END; $$;
-- +goose StatementEnd
CREATE CONSTRAINT TRIGGER questionnaire_public_receipt_complete_before_commit AFTER INSERT OR UPDATE ON public.questionnaire_public_submission_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_public_receipt_complete();
-- +goose StatementBegin
CREATE FUNCTION public.aicrm_questionnaire_public_management_receipt_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.questionnaire_public_management_receipts WHERE id=NEW.id AND state='completed') THEN RAISE EXCEPTION 'public management receipt must complete in reservation transaction' USING ERRCODE='23514'; END IF; RETURN NULL; END; $$;
-- +goose StatementEnd
CREATE CONSTRAINT TRIGGER questionnaire_public_management_receipt_complete_before_commit AFTER INSERT OR UPDATE ON public.questionnaire_public_management_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_public_management_receipt_complete();
