CREATE FUNCTION public.aicrm_questionnaire_public_receipt_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' OR OLD.state='completed' OR NEW.state<>'completed' OR NEW.definition_id IS DISTINCT FROM OLD.definition_id OR NEW.anonymous_digest IS DISTINCT FROM OLD.anonymous_digest OR NEW.submission_key_digest IS DISTINCT FROM OLD.submission_key_digest OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'invalid public receipt transition' USING ERRCODE='55000'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER questionnaire_public_receipt_transition BEFORE UPDATE OR DELETE ON public.questionnaire_public_submission_receipts FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_public_receipt_immutable();
-- +goose StatementBegin
CREATE FUNCTION public.aicrm_questionnaire_public_management_receipt_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' OR OLD.state='completed' OR NEW.state<>'completed' OR NEW.operation IS DISTINCT FROM OLD.operation OR NEW.actor_scope IS DISTINCT FROM OLD.actor_scope OR NEW.key_digest IS DISTINCT FROM OLD.key_digest OR NEW.payload_digest IS DISTINCT FROM OLD.payload_digest OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'invalid public management receipt transition' USING ERRCODE='55000'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER questionnaire_public_management_receipt_transition BEFORE UPDATE OR DELETE ON public.questionnaire_public_management_receipts FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_public_management_receipt_immutable();
CREATE TRIGGER questionnaire_public_submissions_immutable BEFORE UPDATE ON public.questionnaire_public_submissions FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_submission_immutable();
CREATE TRIGGER questionnaire_public_submission_answers_immutable BEFORE UPDATE ON public.questionnaire_public_submission_answers FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_submission_immutable();
-- +goose StatementBegin
CREATE FUNCTION public.aicrm_questionnaire_public_definition_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' OR OLD.state<>'public' OR NEW.state<>'disabled' OR NEW.questionnaire_id IS DISTINCT FROM OLD.questionnaire_id OR NEW.definition_version IS DISTINCT FROM OLD.definition_version OR NEW.slug IS DISTINCT FROM OLD.slug OR NEW.answer_display_mode IS DISTINCT FROM OLD.answer_display_mode OR NEW.title IS DISTINCT FROM OLD.title OR NEW.description IS DISTINCT FROM OLD.description OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.published_at IS DISTINCT FROM OLD.published_at OR NEW.disabled_at IS NULL THEN RAISE EXCEPTION 'public definition is immutable except public to disabled' USING ERRCODE='55000'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER questionnaire_public_definitions_immutable BEFORE UPDATE OR DELETE ON public.questionnaire_public_definitions FOR EACH ROW EXECUTE FUNCTION public.aicrm_questionnaire_public_definition_immutable();
